// Original parallel reading material. Follows textbook learning functions without reproducing its stories.
const syncReadings=[];
const srChoice=(prompt,answer,options,explain)=>({prompt,answer,options,explain,kind:'choice'});
const srInput=(prompt,answer,explain)=>({prompt,answer,explain,kind:'input',hint:'按本题指定语境和形式填写，保留必要重音。'});
function sr(n,title,level,scenes,paragraphs,words,hard,usage,culture,checks){
 const id='sr-'+String(n).padStart(2,'0');const r={id,chapter:n<=18?n:null,title,level,scenes,paragraphs:paragraphs.map(([es,zh])=>({es,zh})),words,hard,usage,culture,questions:checks.map((q,i)=>({...q,id:id+'-q'+i,level,cat:'分级阅读',readingId:id}))};
 for(const q of r.questions){questionBank.push(q);byId.set(q.id,q)}syncReadings.push(r);
}
sr(1,'到达以后，先把话说清楚','A1',['机场问候','在车上询问事物'],[
['Lina llega a Madrid por la mañana. En el aeropuerto ve a Diego, un amigo de su familia. Diego dice: «Hola, Lina. ¿Qué tal?». Lina está cansada, pero está contenta. Responde: «Bien, gracias. ¿Y tú?». No necesita contar toda su vida para saludar.','Lina 上午到达马德里。在机场，她见到了家里的朋友 Diego。Diego 说：“你好，Lina，你好吗？”Lina 虽然累，却很高兴。她回答：“挺好，谢谢，你呢？”打招呼时不需要把自己的整个人生都说一遍。'],
['Antes de salir, buscan la mochila de Lina. Es pequeña y azul. Diego pregunta: «¿Esta es tu mochila?». Ella responde que sí. Luego caminan hasta la parada de taxis. Lina escucha palabras nuevas y pide a su amigo que hable despacio.','出发前，他们找 Lina 的背包。背包小小的，是蓝色的。Diego 问：“这是你的背包吗？”她回答是。随后他们走到出租车站。Lina 听到了生词，请朋友说慢一点。'],
['En el taxi, Lina mira por la ventana. Ve una plaza, una fuente y un edificio alto. Pregunta: «¿Qué es esto?». Diego responde: «Es una fuente». Después señala un edificio: «Eso es un museo». Lina repite las palabras con calma.','在出租车上，Lina 看向窗外。她看到一个广场、一座喷泉和一栋高楼，问：“这是什么？”Diego 回答：“这是一座喷泉。”随后他指向一栋建筑：“那是一座博物馆。”Lina 慢慢重复这些词。'],
['Al llegar a casa, Lina escribe tres expresiones: hola, gracias y ¿qué es esto? También anota la fuente y el museo. Aprende los nombres con el artículo. Hoy no entiende todo, pero ya puede saludar, agradecer y preguntar por una cosa.','到家后，Lina 写下三个表达：你好、谢谢、这是什么。她还记下 la fuente 和 el museo，把名词连冠词一起学。今天她还不能全部听懂，但已经能问候、道谢和询问一样东西。']
],['aeropuerto','mochila','plaza','fuente','edificio','museo','gracias','despacio'],[
['Lina está cansada, pero está contenta.','Lina 累，但她很高兴。','两处 está 都配单数 Lina；cansada/contenta 也描述她。pero 把两种并存状态连接起来，不表示前半句不真实。'],
['Aprende los nombres con el artículo.','她把名字连冠词一起学。','aprende 的省略主语为 Lina；los nombres 为所学内容，con el artículo 说明学习方式。']
],[['回应问候','¿Qué tal? 常作简短问候；Bien, gracias. ¿Y tú? 把话题回给对方。需详细回答还是简短回应，要看关系与情境。'],['指未知事物','¿Qué es esto? 中 esto 可指尚未命名的东西；命名后可用 esta fuente、este museo。不要把中性 esto 直接放到名词前。']],
['见面礼与个人边界','贴面礼、握手或点头都可出现在西语交际中，具体取决于地区、关系和个人偏好，不按性别制定一条普遍强制规则。','初次见面可先口头问候、观察对方的表示；不确定时说 ¿Te doy la mano? 或简单保持自然距离。礼貌在于尊重双方习惯。','称呼和身体接触的选择不是语言水平考试。会说 Hola、Mucho gusto 和 Gracias，已经能完成友好的初次交流。'],[
 srChoice('Lina 在哪里先见到 Diego？','机场',['机场','博物馆','餐厅'],'第一段明确说 En el aeropuerto。'),srChoice('Diego 把 fuente 解释成什么？','喷泉',['喷泉','出租车','背包'],'第三段的指认对象为 fuente。'),srInput('指未知物件：¿Qué es ___?（用 esto）','esto','中性 esto 可指尚未命名的事物，不限定名词。'),srInput('Lina ___ cansada.（estar，现在时）','está','单数第三人称 estar 为 está，保留重音。'),srChoice('初次见面一定必须贴面吗？','不，需看地区、关系和个人意愿',['不，需看地区、关系和个人意愿','所有人必须','只看年龄即可'],'文化说明强调具体语境和个人偏好。'),srChoice('la fuente 中 la 的作用是：','阴性单数冠词',['阴性单数冠词','表示昨天','代替动词'],'连冠词记名词能保留语法性信息。')]);
sr(2,'介绍朋友，也给对方开口的机会','A1',['在家介绍室友','谈邻居的职业和来源'],[
['Por la tarde, Diego presenta a Lina a dos vecinos. «Esta es Irene y este es Pablo», dice. Irene estudia historia. Pablo trabaja en una librería. Lina responde: «Mucho gusto». No conoce sus apellidos y todavía no sabe qué forma de tratamiento prefieren.','下午，Diego 把 Lina 介绍给两位邻居。“这是 Irene，这是 Pablo。”Irene 学历史，Pablo 在书店工作。Lina 回应：“很高兴认识你们。”她不知道他们的姓，也还不知道他们喜欢怎样被称呼。'],
['Irene señala dos sillas: «Estas son para vosotras». Después presenta a sus amigas, Marta y Sara. Lina dice: «Encantada». Usa la forma femenina porque habla de sí misma. Todos escuchan los nombres y dejan tiempo para responder.','Irene 指着两把椅子说：“这是给你们的。”随后她介绍了朋友 Marta 和 Sara。Lina 说“Encantada”，因为这里说话者用阴性形式描述自己。大家听清名字，也给对方留下回应的时间。'],
['Pablo pregunta: «¿Todos sois estudiantes?». Diego responde: «No. Irene y Lina son estudiantes. Yo trabajo en una empresa». Hablan de sus países y de las lenguas que usan. Nadie puede saber la nacionalidad de una persona solo por su apellido.','Pablo 问：“你们全都是学生吗？”Diego 回答：“不是，Irene 和 Lina 是学生，我在一家公司工作。”他们谈起各自的国家和使用的语言。不能只凭姓氏就知道一个人的国籍。'],
['A las seis, llega la señora Ramos. Lina la saluda con «Buenas tardes». Luego pregunta cómo puede llamarla. La vecina prefiere su nombre, Clara. Lina lo anota: aprender una lengua también es aprender a preguntar con respeto.','六点时 Ramos 女士到了。Lina 说“下午好”，然后问怎样称呼她。邻居更愿意被叫名字 Clara。Lina 记下这一点：学语言也包括学会尊重地询问。']
],['vecino','presentar','silla','estudiante','empresa','apellido','tarde','señora'],[
['Usa la forma femenina porque habla de sí misma.','她用阴性形式，因为她在说自己。','usa 配 Lina；porque 给原因。encantada 与说话者对应，而 bienvenida 与被欢迎对象对应，两种一致来源要分开。'],['Nadie puede saber la nacionalidad de una persona solo por su apellido.','不能仅凭姓知道一个人的国籍。','nadie 是否定主语；其前不再加 no。poder 后 saber 保持原形；solo por 表仅凭。']],
[['介绍人物','Este es… / Esta es… / Estos son… / Estas son… 先按所指人物或群体选择，再让 ser 配单复数。'],['尊称的搭配','Don/Doña 常与名字相连，señor/señora 常与姓氏相连。实际优先使用对方偏好的称呼，不自动按年龄或外貌分配。']],
['早、中、晚问候的分界','Buenos días、Buenas tardes、Buenas noches 的使用与当地作息、天色和情境有关，不是所有国家严格按同一钟点切换。','第一次接触新地方时，可跟随当地常用表达并听对方如何回应；Hola 则是较灵活的常见问候。','不要把某个国家的习惯推广成整个西语世界的固定时刻表。认识差异后，目标是清楚友好地沟通。'],[
 srChoice('Pablo 在哪里工作？','书店',['书店','医院','机场'],'第一段说 trabaja en una librería。'),srChoice('Ramos 女士更愿意被怎样称呼？','Clara',['Clara','Pablo','教授'],'第四段说明她偏好自己的名字 Clara。'),srInput('介绍 Irene：___ es Irene.','esta','指称女性单数用 esta；本站输入不区分句首大小写。'),srInput('介绍两位女性：Estas ___ mis amigas.','son','复数主语配 ser 的 son。'),srChoice('问候语的钟点分界是否各地完全一样？','不是，要结合当地习惯',['不是，要结合当地习惯','是，全世界一样','只由姓氏决定'],'文化讲解强调地区与情境。'),srChoice('女性说话者表示很高兴认识对方，可说：','Encantada.',['Encantada.','Encantado（在本题的自我配合中）.','Encantadas soy.'],'此处与说话者性别配合，不看对方性别。')]);
sr(3,'欢迎来访，描述人时多说具体信息','A1',['欢迎客人并提供饮品','介绍来源与外貌'],[
['El sábado, Lina visita a Clara. Clara abre la puerta y dice: «Bienvenida». Después pregunta: «¿Quieres tomar algo?». Lina responde: «Agua, por favor». Si no quiere beber, también puede decir «No, gracias». Una invitación no obliga a aceptar.','周六，Lina 拜访 Clara。Clara 开门说“欢迎”，然后问：“想喝点什么吗？”Lina 回答：“请给我水。”如果不想喝，也可以说“不用了，谢谢”。受到邀请并不意味着必须接受。'],
['En el salón hay varias fotografías. Clara presenta a su familia. Su hermana es alta y tiene el pelo corto. Su hermano es sociable y habla mucho. Lina aprende a separar la descripción física de los comentarios sobre la personalidad.','客厅里有几张照片。Clara 介绍家人：她的姐姐个子高，留短发；她的哥哥好交际，话很多。Lina 学着把外貌描述与性格描述区分开。'],
['«¿De dónde eres?», pregunta Clara. Lina dice que es de China y vive ahora en Madrid. Clara nació en Valencia, pero su madre es de Andalucía. Tener relaciones con varios lugares no es una contradicción. Una respuesta puede necesitar más de un nombre.','Clara 问：“你来自哪里？”Lina 说自己来自中国，目前住马德里。Clara 出生于瓦伦西亚，但母亲来自安达卢西亚。与多个地方有联系并不矛盾，回答有时需要不止一个地名。'],
['Antes de volver a casa, Lina agradece la visita. No necesita describir el cuerpo de todas las personas que conoce. Prefiere preguntar por sus intereses y escuchar. En su cuaderno escribe ser alta, tener el pelo corto y ser de Valencia.','回家前，Lina 为这次招待道谢。她不需要描述每位新认识者的身体，更愿意询问兴趣并倾听。她在笔记本记下 ser alta、tener el pelo corto 和 ser de Valencia。']
],['bienvenido','tomar','agua','pelo','alto','sociable','origen','Valencia'],[
['Su hermana es alta y tiene el pelo corto.','她的姐姐个子高，留短发。','身高可用 ser＋形容词；头发特征常用 tener el pelo＋形容词。alta 配 hermana，corto 配 pelo。'],['Tener relaciones con varios lugares no es una contradicción.','与多个地方有联系并不矛盾。','原形短语作为整体主语，es 单数；varios lugares 是其内部补语，不控制 es。']],
[['欢迎与回应','bienvenida 描述被欢迎的女性；多位女性可用 bienvenidas。Encantada 则常按说话者配合。'],['来源与住处','ser de＋来源、vivir en＋住处、nacer en＋出生地各自表达不同信息；不要都只译成“来自”。']],
['西班牙的地区与城市','Madrid 是西班牙首都，Valencia 在地中海沿岸，Andalucía 是南部自治区；地区、城市、国家不是同一层级。','paella 与瓦伦西亚联系密切，安达卢西亚也有多样的地方饮食和艺术传统。一个地区不能只由一种菜或一个刻板印象定义。','介绍自己的来源可以同时说国家、家乡和现居地。听不明白层级时问 ¿Es una ciudad o una región? 比凭空猜更有帮助。'],[
 srChoice('Lina 接受了什么饮品？','水',['水','咖啡','酒'],'第一段明确回答 Agua, por favor。'),srChoice('Clara 出生在哪里？','Valencia',['Valencia','中国','Andalucía'],'第三段说明她出生于 Valencia，母亲来自 Andalucía。'),srInput('来源：Soy ___ China.','de','ser de 引出来源。'),srInput('Su hermana ___ el pelo corto.（tener）','tiene','tener 配单数 hermana，用 tiene。'),srChoice('Andalucía 在这里属于：','地区/自治区',['地区/自治区','另一个国家','人物姓氏'],'文化说明区分地区与城市层级。'),srChoice('corto 在 el pelo corto 中与谁配合？','pelo',['pelo','说话者','hermana'],'形容词描述头发，配阳性单数 pelo。')]);
sr(4,'先问清楚要找什么，再问在哪里','A1',['校园里问路','谈距离与学习'],[
['Lina busca la oficina de su facultad. Ve a una estudiante y pregunta: «Perdona, ¿dónde está la oficina?». La estudiante conoce el lugar. Explica que está al final del pasillo, a la derecha. Lina repite la información para comprobar que la entiende.','Lina 在找学院办公室。她看见一名学生，问：“打扰一下，办公室在哪里？”那名学生知道这个地方，解释说在走廊尽头右边。Lina 重复一遍，确认自己理解了。'],
['Después necesita comprar un cuaderno, pero no sabe si hay una papelería cerca. Por eso pregunta: «¿Hay una papelería por aquí?». No está localizando una tienda ya conocida: primero necesita saber si existe alguna en la zona.','随后她需要买笔记本，却不知道附近有没有文具店，所以问：“这一带有文具店吗？”她不是在定位一家已知店铺，而是先确认这片区域是否有这样的店。'],
['En la cafetería encuentra a Mateo, un estudiante de Guinea Ecuatorial. Él estudia bellas artes. La papelería está a diez minutos andando. No está muy lejos, pero Lina no tiene mucho tiempo. Decide ir después de clase.','在咖啡厅她遇见了来自赤道几内亚的学生 Mateo。他学美术。文具店步行约十分钟，不算远，但 Lina 时间不多，决定下课后再去。'],
['Los dos comparan las lenguas que usan en casa y en la universidad. El español se habla en varios continentes. Para entender a Mateo, Lina escucha con atención y pregunta por una palabra nueva. Hablar de otra manera no significa hablar peor.','两人比较了在家和在大学使用的语言。西语在多个大洲使用。为了听懂 Mateo，Lina 仔细听，并询问一个生词。说法不同并不意味着说得更差。']
],['oficina','facultad','pasillo','derecha','papelería','cafetería','lejos','andando'],[
['No está localizando una tienda ya conocida.','她不是在定位一家已知的店。','no 是否定当前动作，已知性影响 hay/estar 的信息组织；不应只机械检查有没有冠词。'],['La papelería está a diez minutos andando.','文具店步行约十分钟。','estar a＋时长＋andando 表到达所需步行时间；不是物理距离数值。']],
[['存在与定位','¿Hay una papelería? 引入存在；¿Dónde está la papelería? 定位可识别对象。真实语境有其他限定结构，不把两句口诀扩成无例外禁令。'],['距离','cerca de/lejos de、a diez minutos andando、a dos kilómetros de… 分别说相对位置、行程时间或距离。']],
['西语国家、地区与首都','西语世界涉及欧洲、美洲和非洲。把国家、领地、首都和最大城市分开学习，比只背一个“国家总数”可靠。','例如 México—Ciudad de México，Colombia—Bogotá，Argentina—Buenos Aires，España—Madrid。Bolivia 的法定首都与政府所在地需要区分；Puerto Rico 也不应被误写为独立主权国家。','地理信息会变化。阅读旧教材时应区分当时表述和现行资料；语言学习先能识别地名、表达来源，并知道到哪里核实最新行政信息。'],[
 srChoice('办公室在哪里？','走廊尽头右边',['走廊尽头右边','咖啡厅楼上','机场'],'第一段给出 al final del pasillo, a la derecha。'),srChoice('Lina 何时打算去文具店？','下课后',['下课后','立刻不去上课','昨天'],'第三段说 después de clase。'),srInput('引入是否存在：¿___ una papelería por aquí?','hay','存在疑问用 hay。'),srInput('La oficina ___ al final del pasillo.','está','定位已知办公室，estar 单数第三人称。'),srChoice('Puerto Rico 在地理学习中：','应与独立主权国家区分',['应与独立主权国家区分','必定是西班牙城市','是 Argentina 的首都'],'文化说明强调政治地位层级。'),srChoice('a diez minutos andando 表示：','步行所需时间',['步行所需时间','十公里的距离','上午十点'],'不是任意把分钟换成公里。')]);
sr(5,'看课表，也听清对方的安排','A1',['办公室询问时间','咖啡厅商量计划'],[
['El lunes, Lina va a la oficina para preguntar por su horario. La empleada dice: «La clase de español es a las nueve y media». Lina repite la hora. Para saber la hora actual pregunta «¿Qué hora es?». Para preguntar por la clase usa «¿A qué hora es?».','周一，Lina 去办公室询问课表。工作人员说：“西语课在九点半。”Lina 重复时间。问现在几点用 ¿Qué hora es?；问课程在几点则用 ¿A qué hora es?。'],
['La clase termina a la una. Después, Lina quiere comer con Irene. Primero comprueba si su amiga puede ir. No confunde un deseo con un acuerdo: decir «Quiero ir» no significa que las dos ya tengan un plan confirmado.','课一点结束。之后 Lina 想与 Irene 吃饭，先确认朋友能不能去。她没有把愿望当成约定：说 Quiero ir 不意味着两人已经确认了计划。'],
['En la cafetería, Irene propone ver una película. Lina responde: «Podemos ir mañana, pero hoy tengo que estudiar». Buscan otra hora y deciden encontrarse a las seis. Antes de despedirse, confirman el lugar y el día.','在咖啡厅，Irene 提议看电影。Lina 回答：“我们可以明天去，但今天我得学习。”她们另找时间，决定六点见面。道别前，她们确认地点和日期。'],
['Lina también quiere comprar un cuaderno. La tienda pequeña cierra al mediodía, pero otra sigue abierta. Mira el horario en la puerta. No supone que todas las tiendas cierren a la misma hora ni que el horario de internet esté siempre actualizado.','Lina 还想买笔记本。小店中午关门，另一家仍开着。她查看门口营业时间，不假定所有商店同时关门，也不认为网上时间永远最新。']
],['horario','empleada','terminar','querer','poder','película','encontrarse','tienda'],[
['No confunde un deseo con un acuerdo.','她不把愿望与约定混同。','confundir A con B 为把A与B混淆；这里在说明交际意图，不仅是时态形式。'],['Podemos ir mañana, pero hoy tengo que estudiar.','我们明天可以去，但我今天必须学习。','podemos 配我们，tengo 配我；ir/estudiar 分别受 poder、tener que 要求保持原形。']],
[['三个动词框架','ir a＋原形谈计划，querer＋原形谈意愿，poder＋原形谈能力或许可。先区分意图，再判断是否已达成共同安排。'],['连词变体','y 在后词以 /i/ 起音的常见环境可变 e：español e inglés；但 hielo 的起音不是纯 /i/，不能只看字母。o 在 /o/ 起音前可变 u，如 siete u ocho。']],
['商铺营业时间','营业时间取决于城市、行业、商家和日期；小店、连锁店、周末与节假日可能不同，不把午休当成全体商家的强制统一安排。','实用问法：¿A qué hora abre/cierra? ¿Está abierto los domingos? 看清门上时间，必要时再次确认。','教材里的具体时刻可用于练语言，实际出行应查目标店铺的当前信息。会问、会核对，比背一张全国统一时刻表实用。'],[
 srChoice('西语课几点开始？','九点半',['九点半','一点','六点'],'首段说明 a las nueve y media。'),srChoice('看电影最终约在几点？','六点',['六点','九点半','十二点'],'第三段说明 a las seis。'),srInput('La clase es ___ las nueve y media.','a','事件发生时间点用 a las。'),srInput('Hoy tengo que ___.（estudiar）','estudiar','tener que 后用原形。'),srChoice('实际去商店前，最可靠的做法是：','核对目标商家的当前营业时间',['核对目标商家的当前营业时间','认为全国同时午休','只背教材一个时刻'],'文化说明强调具体机构和日期。'),srChoice('正确常见表达：','español e inglés',['español e inglés','español o inglés（在本题“和”义中）','español e hielo（机械按i字母）'],'e 的选择看后词起音，不只看字母。')]);
sr(6,'看房间：位置、数量和感受分开说','A1',['咖啡厅描述公寓','到家参观房间'],[
['Lina habla con Irene sobre su piso. Tiene dos habitaciones y un salón pequeño. La cocina está al lado del salón. Irene pregunta si hay mucha luz. Lina dice que por la mañana entra el sol por una ventana grande.','Lina 和 Irene 谈自己的公寓。公寓有两个房间和一个小客厅，厨房在客厅旁边。Irene 问采光好不好。Lina 说上午阳光从一扇大窗户照进来。'],
['Para explicar la distribución, Lina dibuja un plano. La mesa está delante de la ventana. Hay una lámpara encima de la mesa y una caja debajo de la silla. Enfrente de la puerta está el armario. Un plano ayuda a comprobar las relaciones.','为了说明布局，Lina 画了平面图。桌子在窗前，桌上有一盏灯，椅子下面有盒子。柜子在门对面。平面图能帮助核对位置关系。'],
['Por la tarde, Irene visita el piso. Lina dice: «Mi habitación es pequeña, pero hoy está ordenada». La estantería es bastante alta. El escritorio está un poco sucio. Estas descripciones no dicen exactamente lo mismo: una habla de tamaño y otra de estado.','下午 Irene 来参观。Lina 说：“我的房间小，但今天很整洁。”书架相当高，书桌有点脏。这些描述不完全相同：一类说尺寸，另一类说状态。'],
['Irene vive sola, pero no se siente sola. Le gusta tener tiempo para leer. Lina anota dos usos de solo: vivir sola no significa vivir solamente para estudiar. También aprende que «un poco más cómodo» puede ser una mejora, no una crítica.','Irene 一个人住，但不感到孤独。她喜欢留出时间读书。Lina 记下 solo 的不同用法：一个人住不等于只为学习而生活。她还学到 un poco más cómodo 可以表示更舒服一点，是改善而非批评。']
],['piso','habitación','salón','ventana','encima','debajo','armario','estantería'],[
['Mi habitación es pequeña, pero hoy está ordenada.','我的房间小，但今天很整洁。','es 描述尺寸，está 描述当前状态；两处形容词都配 habitación 阴性单数。'],['Irene vive sola, pero no se siente sola.','Irene 一个人住，但不感到孤独。','sola 在相邻语境中可涉及独居与孤独感，不应机械当作完全同义。']],
[['方位词连结构记','encima de、debajo de、delante de、detrás de、enfrente de、dentro de、fuera de 等连接参照物；注意 del 是 de＋el。'],['程度和词义','muy、bastante、un poco 的搭配受意义和语境影响。un poco 常缓和不理想描述，但“只能接贬义词”过于绝对；un poco más cómodo 就可表达改善。solo 的形容词与副词用法也需看所修饰对象。']],
['西语的使用范围与学习路径','西语在多个国家和地区使用，各地词汇、口音和人称系统有差异；使用人数随统计年份和“母语/学习者”等口径变化。','不要把某个年份的总人数当作永远不变的事实，也不要把“某种语言最优美”之类修辞当语言学排名。','学习时先选稳定参照，再扩展其他地区输入。目标是理解并交流，而不是模仿一个想象中的全世界统一口音。'],[
 srChoice('台灯在哪里？','桌子上面',['桌子上面','椅子下面','门外'],'第二段说 encima de la mesa。'),srChoice('今天房间处于什么状态？','整洁',['整洁','空无一人','特别大'],'第三段说 hoy está ordenada。'),srInput('La caja está debajo ___ la silla.','de','方位短语 debajo de 保留介词。'),srInput('Mi habitación ___ pequeña.（ser）','es','尺寸描述用本句的 ser，主语单数。'),srChoice('西语使用人数是否可把旧教材数字永久固定？','不，应注明时间和统计口径',['不，应注明时间和统计口径','是，永不变化','只与形容词性别有关'],'文化解读区分统计时间和范围。'),srChoice('un poco más cómodo 可以表示：','更舒服一点，属于改善',['更舒服一点，属于改善','所有场合都必是批评','不能出现在西语中'],'不能把un poco的搭配概括成绝对“只贬义”。')]);
sr(7,'买菜前先问清单位','A1',['路上谈购物与价格','在家点单和核对数量'],[
['El sábado, Lina hace la compra. Antes de entrar en la tienda, mira una lista: tomates, manzanas, leche y pan. Irene va de compras para buscar una chaqueta. Las dos usan la palabra comprar, pero sus planes no son iguales.','周六，Lina 采购日用品。进店前，她看看清单：番茄、苹果、牛奶、面包。Irene 则去逛街买外套。两人都用 comprar 这个词，但安排不相同。'],
['En la frutería, Lina pregunta: «¿A cuánto están las manzanas?». El precio es por kilo, no por cada manzana. Pide medio kilo. Después compra una docena de huevos en otra tienda. Antes de pagar, pregunta cuánto es todo.','在水果店，Lina 问苹果什么价。标价按公斤，不是每个苹果。她买了半公斤，随后在另一家店买了一打鸡蛋。付款前，她问全部一共多少钱。'],
['Al llegar a casa, los vecinos quieren preparar una comida. Pablo hace una llamada para pedir pan. Irene hace una pregunta sobre la cantidad de arroz. Lina revisa la compra: una botella de leche, dos barras de pan y medio kilo de fruta.','到家后，邻居们想准备一顿饭。Pablo 打电话订面包，Irene 询问米的用量。Lina 核对购物结果：一瓶牛奶、两条面包和半公斤水果。'],
['Para tres personas necesitan cantidades diferentes. Un kilo y medio no es lo mismo que medio kilo. Escriben las unidades junto a los números. Cuando una información no está clara, preguntan otra vez. Comprar bien también requiere comprender las medidas.','三个人需要的用量各不相同。一公斤半不等于半公斤。他们把单位写在数字旁，不清楚时再问一遍。采购也需要理解计量方式。']
],['compra','chaqueta','manzana','kilo','docena','huevo','botella','cantidad'],[
['El precio es por kilo, no por cada manzana.','价格按公斤，不按每个苹果。','por 引出计价单位；cada限定单个对象，不把单位价格与总价混同。'],['Un kilo y medio no es lo mismo que medio kilo.','一公斤半不等于半公斤。','前者1.5公斤，后者0.5公斤；medio的位置参与构成数量意思。']],
[['三种价格问题','按重量/体积可问 ¿A cuánto está…?；具体商品可问 ¿Cuánto cuesta…?；总价可问 ¿Cuánto es todo?。先确认计价方式，不只背中文“多少”。'],['单位和 hacer 搭配','medio kilo、un cuarto de kilo、un kilo y medio、una docena 为不同数量；hacer una llamada/una pregunta/la compra各有常见搭配，不将hacer全部逐字译成做。']],
['西语世界的菜肴','paella 与瓦伦西亚、tacos 与墨西哥、ceviche 与秘鲁等有文化联系，但每道菜都有地区版本，名称不能替代了解配料。','点餐可以问 ¿Qué lleva? 或 ¿Cómo se prepara?。例如tortilla在不同地方可能指不同食物，应读菜单和听具体说明。','介绍本国菜肴时，用食材、做法、口味三个维度解释；“和某道中国菜差不多”可辅助理解，却不应把两者完全等同。'],[
 srChoice('苹果标价按什么单位？','公斤',['公斤','每个','每打'],'第二段明确 por kilo。'),srChoice('谁打电话订面包？','Pablo',['Pablo','Lina','工作人员'],'第三段说 Pablo hace una llamada。'),srInput('半公斤：___ kilo.','medio','kilo 阳性，half-kilo为medio kilo。'),srInput('一打鸡蛋：una ___ de huevos.','docena','docena表示十二个这一组。'),srChoice('tortilla 的意思：','应结合地区和菜肴语境',['应结合地区和菜肴语境','全世界永远同一种食物','就是所有米饭'],'文化讲解强调不同地区使用。'),srChoice('un kilo y medio 是：','1.5公斤',['1.5公斤','0.5公斤','0.25公斤'],'先一公斤，再加半公斤。')]);
sr(8,'试衣服时，喜欢、偏好和许可各有表达','A1',['挑选材质与衣服','试衣与比较'],[
['Irene busca una falda para una fiesta. En la tienda hay una de seda y otra de algodón. Dice: «Me gusta la de seda, pero prefiero la de algodón para todos los días». No está diciendo que la otra sea mala; está explicando una preferencia.','Irene 为聚会挑裙子。店里有丝绸的，也有棉的。她说：“我喜欢丝的，但日常更偏好棉的。”这不表示另一件不好，而是在解释偏好。'],
['Lina mira unas gafas. «Estas me gustan», dice. El verbo va en plural porque habla de las gafas. Después pregunta si puede probarse una chaqueta. La dependienta le indica dónde están los probadores. Lina pide permiso antes de entrar.','Lina 看上一副眼镜，说：“我喜欢这个。”因为说的是 gafas，动词用复数。随后她问能否试一件外套。店员指出试衣间位置，Lina 先征得许可再进去。'],
['La chaqueta azul es bonita, pero las mangas son cortas. Lina pregunta por una talla mayor. No basta con saber el color: tiene que explicar qué parte no le queda bien. La dependienta trae otra chaqueta y Lina la prueba.','蓝外套好看，但袖子短。Lina 问有没有大一号的。只会说颜色还不够，还要说明哪里不合身。店员拿来另一件，Lina 试穿。'],
['Antes de pagar, preguntan dónde pueden cambiar la ropa si hay un problema. Guardan el recibo. Al salir ven un mercadillo en la plaza. Allí las condiciones de venta pueden ser diferentes. Preguntar primero evita suponer que todas las tiendas tienen las mismas normas.','付款前，她们询问衣服有问题时去哪里换，并保留小票。出来后看到广场上的露天集市，那里的交易条件可能不同。先问清楚，就不会以为所有店铺规则都一样。']
],['falda','seda','algodón','preferir','gafas','probador','manga','talla'],[
['El verbo va en plural porque habla de las gafas.','动词用复数，因为她谈的是眼镜。','gafas 是gustar的主语；me标体验者，不决定单复数。'],['No basta con saber el color.','只知道颜色还不够。','bastar con＋原形说明充分条件；这里强调交际任务不只命名物品。']],
[['偏好','preferir A a B 表更偏好A而非B；prefiero与me gusta不是同一结构，不说me prefiero esta falda来表示普通偏好。'],['许可与试穿','¿Puedo probarme…? 由poder承担人称，probar保持原形，me后接。talla与材料、颜色、合身程度可分别提问。']],
['mercado 与 mercadillo','mercado常指市场，mercadillo常见于露天或定期摊位市场，但经营方式和销售内容会因地方而异。','在不同商家购买时，可询问价格、付款、退换和收据；不要假定所有露天摊位都可议价，也不要把一家店的规则推广到全国。','pescadería、carnicería、frutería、verdulería等店名可帮助推测商品。辨认类别后仍要核实具体卖什么。'],[
 srChoice('Irene 日常更偏好哪种材质？','棉',['棉','丝绸','皮革'],'首段说 prefiero la de algodón para todos los días。'),srChoice('蓝外套哪里不合适？','袖子短',['袖子短','没有袖子','帽子太小'],'第三段明确las mangas son cortas。'),srInput('Me ___ estas gafas.','gustan','gafas复数控制gustan。'),srInput('¿Puedo ___ esta chaqueta?（probarse，按yo）','probarme','poder后原形，代词me与试穿者yo配。'),srChoice('mercadillo 的退换规则应：','向具体商家确认',['向具体商家确认','认为全国所有摊位相同','只看词尾判断'],'文化说明强调具体交易情境。'),srChoice('“我更偏好A而非B”的常见框架：','Prefiero A a B.',['Prefiero A a B.','Me prefiero A de B.','Yo gusta A a B.'],'preferir的搭配与gustar不同。')]);
sr(9,'起床、照顾别人和安排一天','A1',['早起与作息','运动、学习和日常习惯'],[
['Mateo se levanta a las siete los días de clase. Primero se lava la cara y después prepara el desayuno. Su hermana pequeña todavía duerme. A veces él la despierta, pero hoy la niña se despierta sola. Los dos verbos no describen exactamente la misma relación.','上课日 Mateo 七点起床，先洗脸再准备早餐。妹妹还睡着。有时他叫醒妹妹，但今天妹妹自己醒来。两种动词结构描述的关系不完全相同。'],
['Lina pregunta: «¿A qué hora te acuestas?». Mateo responde que depende del día. Acostarse es ir uno mismo a la cama; acostar a un niño es ayudar a otra persona a acostarse. El pronombre puede cambiar el papel de los participantes.','Lina 问他几点睡觉，Mateo 说要看哪一天。acostarse 是自己躺下；acostar a un niño 是让孩子躺下。代词可能改变参与者的角色。'],
['Por la tarde hacen deporte en un parque. No hacen ejercicio toda la tarde: después estudian una hora. Lina anota por la mañana, por la tarde y por la noche. Las usa para hablar de periodos del día sin dar siempre una hora exacta.','下午他们在公园运动，但不是一整个下午都在锻炼，之后还学习一小时。Lina 记下 por la mañana、por la tarde、por la noche，用来谈一天中的时段，不必每次给出精确钟点。'],
['Para una cita concreta dicen «a las cinco de la tarde». El horario de cada persona depende de su trabajo y sus responsabilidades. Ninguno supone que todos los habitantes de un país se levanten, coman o se acuesten a la misma hora.','约定具体时间时，他们说“下午五点”。每个人的作息取决于工作和责任，没人认为同一国家的人都同时起床、吃饭、睡觉。']
],['levantarse','lavarse','despertar','acostarse','desayuno','deporte','parque','responsabilidad'],[
['Hoy la niña se despierta sola.','今天女孩自己醒来。','se与醒来者相关，sola也描述女孩；对比él la despierta中的la为女孩直接宾语。'],['No hacen ejercicio toda la tarde.','他们并非整个下午都在运动。','否定范围涉及整段下午，不应直接推成完全没有运动。']],
[['带代词与不带代词','levantarse/levantar、acostarse/acostar、despertarse/despertar要放进完整句看参与者，不能把所有se简单译成自己。'],['时段与时点','por la tarde 表下午时段，a las cinco de la tarde 给具体五点。todo el día与todos los días分别为一整天与每天。']],
['作息差异','一些西班牙生活场景中的午晚餐时间可能比学习者原来习惯的晚，但城市、行业、家庭和个人差异很大。','约饭时最好问 ¿A qué hora comemos/cenamos?，并复核日期与地点，而不是按国籍猜时间。','读到作息介绍中的全国性概括时，将其当了解某种常见现象的起点，随后用具体人的安排更新理解。'],[
 srChoice('上课日 Mateo 几点起床？','七点',['七点','五点','十一点'],'首段给出a las siete。'),srChoice('下午运动后他们做什么？','学习一小时',['学习一小时','立刻睡觉','去机场'],'第三段说 después estudian una hora。'),srInput('Mateo ___ levanta a las siete.','se','单数第三人称levantarse用se。'),srInput('下午时段：___ la tarde.','por','本题指定时段表达por la tarde。'),srChoice('约定具体用餐时间时应：','询问对方并确认安排',['询问对方并确认安排','只按国籍猜测','认为所有家庭一样'],'文化讲解强调具体日程。'),srChoice('él la despierta 中 la 指：','被叫醒的女孩',['被叫醒的女孩','他自己的房间','一段时间'],'这里是直接宾语代词，并非反身se。')]);
sr(10,'先确认地点，再把电话里的话说清楚','A2',['指路与选择路线','接听电话和传达信息'],[
['Lina quiere ir a una exposición. Diego le explica el camino: primero debe salir de la estación, cruzar la calle y seguir recto hasta la plaza. Después tiene que girar a la izquierda. Lina repite cada paso y pregunta por un edificio que pueda reconocer.','Lina 想去看展览。Diego 告诉她路线：先出车站、过马路、一直走到广场，再左转。Lina 重复各步骤，并询问一个自己能辨认的建筑地标。'],
['Diego dice «sube por esta calle», pero Lina no lo interpreta automáticamente como ir hacia el norte. Mira la pendiente y el plano. Algunas instrucciones dependen de la forma del barrio o de una referencia local. Pregunta: «¿Hasta la farmacia?».','Diego 说 sube por esta calle，Lina 没有自动理解成往北走，而是看坡度和平面图。有些指示依赖街区形状或当地参照。她问：“走到药店吗？”'],
['Entonces suena el teléfono. Lina contesta: «Dígame». Es Irene, que pregunta si Diego está con ella. Lina responde que sí y le pasa el teléfono. No da información personal a una persona cuya identidad no conoce. Primero pregunta quién llama.','这时电话响了，Lina 接听说“请讲”。是 Irene，询问 Diego 是否与她在一起。Lina 说是，然后把电话交给他。遇到身份不明的来电者，她先问是谁，不直接透露个人信息。'],
['Al terminar la llamada, comprueban el lugar y la hora de encuentro. Un mensaje breve puede causar una confusión si no dice qué día se refiere a «mañana». Lina envía la fecha completa y el nombre de la entrada de la exposición.','挂断前，他们核对见面地点与时间。简短信息如果没说明“明天”指哪天，也会造成混淆。Lina 发出完整日期和展览入口名称。']
],['exposición','cruzar','seguir','girar','pendiente','llamada','entrada','fecha'],[
['No lo interpreta automáticamente como ir hacia el norte.','她没有自动把它理解为往北走。','lo回指sube这条指令的内容；como引出解释方式，不是地点本身。'],['Un mensaje breve puede causar una confusión si no dice qué día se refiere a mañana.','简短信息若不说明明天是哪天，会造成混淆。','si引条件，qué día为询问缺口；时间指示词须有参照。']],
[['可执行的指路','sigue todo recto、gira a la derecha/izquierda、cruza la calle、hasta…按顺序组织；subir/bajar不自动等于北/南。'],['电话开场','¿Sí?、¿Diga?、¿Dígame?可作常见接听开场。先确认身份，再问是否方便或传达信息，语法上的命令形式不必然等于粗鲁命令。']],
['马德里地标与参观安排','Puerta del Sol、Plaza Mayor、Parque del Retiro和Museo del Prado等名称能作为学习地标与文化入口。','地名用于定位不等于掌握实际入口、开放时间或预约要求。规划行程时把地标名、地址与当前参观信息分别核对。','介绍一处景点时，可说明它是什么、在什么位置、为何想去；无需把城市介绍写成未经更新的营业时刻表。'],[
 srChoice('路线到广场后要怎样转？','左转',['左转','右转','立即上楼'],'第一段说 girar a la izquierda。'),srChoice('来电者是谁？','Irene',['Irene','陌生店员','Clara'],'第三段明确来电人。'),srInput('对 tú：___ todo recto.（seguir，肯定命令）','sigue','seguir肯定tú为sigue。'),srInput('常见接电话：___ .（decir，usted肯定形式后接me）','dígame','diga后接me写dígame并标重音。'),srChoice('sube por esta calle 是否自动等于往北？','不，需看地形与当地参照',['不，需看地形与当地参照','是，永远北','只能表示坐飞机'],'文章特意辨析此误读。'),srChoice('电话中先确认身份的目的之一是：','让信息传达清楚且不过度透露个人信息',['让信息传达清楚且不过度透露个人信息','完全不说西语','证明所有命令式都粗鲁'],'第三段说明先问谁来电。')]);
sr(11,'点餐要能说明顺序，也能说明偏好','A2',['看菜单点餐','谈口味与餐厅差异'],[
['Lina y sus amigos van a comer después de una visita al teatro. En la puerta leen el menú del día. Preguntan si incluye bebida y postre. El camarero explica las opciones. No eligen solo por el nombre: también preguntan qué ingredientes lleva cada plato.','参观剧院后，Lina 与朋友去吃饭。门口有今日套餐，他们问是否含饮品与甜点，服务员说明选项。他们不只看菜名，还询问每道菜的配料。'],
['De primero, Lina quiere ensalada. De segundo pide pescado y, para beber, agua. Irene no desea postre. Dice «Para mí, un café». El camarero confirma el pedido antes de ir a la cocina. Las amigas corrigen una bebida que no han pedido.','Lina 第一道要沙拉，第二道点鱼，饮品要水。Irene 不想吃甜点，说“我来杯咖啡”。服务员进厨房前核对订单，两人纠正了一项没点过的饮品。'],
['Más tarde comentan la comida. A Lina le encanta el pescado. A Irene no le gusta mucho la salsa. No es lo mismo decir que un plato no le gusta que afirmar que está mal preparado. Una opinión personal no es automáticamente una evaluación general.','稍后她们谈论餐食。Lina 非常喜欢鱼，Irene 不太喜欢酱汁。说自己不喜欢一道菜，不等于断定它做得不好。个人喜好不会自动变成普遍评价。'],
['En otro local ven pequeñas raciones para compartir. Preguntan cómo se piden y cuánto cuestan. Las tapas pueden tener formas y precios diferentes según el lugar. Lina evita una regla que ha oído: no supone que todas sean gratis ni que siempre sustituyan una comida completa.','在另一家店，她们看到可分享的小份食物，便问怎样点、价格多少。Tapas 的形式与价格因地而异。Lina 不把听来的说法当统一规则：它们不一定免费，也不一定总能替代完整一餐。']
],['menú','incluir','bebida','postre','ensalada','pescado','salsa','ración'],[
['No es lo mismo decir que un plato no le gusta que afirmar que está mal preparado.','说不喜欢一道菜，与断言它没做好不是一回事。','两个原形短语作比较；gusta与plato配合，le表体验者，不能把体验当事实质量判断。'],['El camarero confirma el pedido antes de ir a la cocina.','服务员去厨房前确认订单。','antes de后接原形，ir的行为者仍为服务员。']],
[['点餐顺序','de primero/de segundo/de postre和para beber分别组织菜单项目；¿Qué lleva?可询问配料，¿Está incluido?可确认包含内容。'],['喜好程度','me encanta、me gusta mucho、me gusta、no me gusta mucho、no me gusta nada程度不同。no me gusta mucho不等于绝对厌恶，注意否定范围。']],
['tapas 与分享小份菜','tapa可指一小份配餐食物，传统解释常联系“盖子”，但名称来历有不同说法，不把一种故事当唯一已证实历史。','tapa、pincho、ración的使用及分量依地区和店家而异，有的收费、有的随饮品附送，先看菜单或询问。','想分享可以说 Para compartir；不清楚分量可问 ¿Para cuántas personas es?。实际交际比背一个“全国免费”说法更可靠。'],[
 srChoice('Lina 第二道点了什么？','鱼',['鱼','牛肉','蛋奶布丁'],'第二段说de segundo pide pescado。'),srChoice('Irene 如何评价酱汁？','不太喜欢',['不太喜欢','认为所有人都爱吃','完全没尝过而下定论'],'第三段说no le gusta mucho la salsa。'),srInput('饮品：___ beber, agua.','para','para beber在点餐中组织饮品项目。'),srInput('Me ___ estos platos.（encantar）','encantan','复数主语estos platos控制encantan。'),srChoice('所有 tapas 都免费吗？','不是，应向店家确认',['不是，应向店家确认','是，全国统一','只看语法时态'],'文化讲解强调店家与地区差异。'),srChoice('no me gusta mucho 的通常程度是：','不太喜欢，不必等于完全讨厌',['不太喜欢，不必等于完全讨厌','与me encanta完全相同','没有否定意义'],'mucho受no影响，范围决定表达程度。')]);
sr(12,'表达意见，也把替代方案说具体','A2',['讨论一个看法','安排周末活动'],[
['El viernes, los vecinos hablan de una película. Diego pregunta: «¿Qué os parece?». Lina cree que la historia es interesante, pero un poco larga. Irene está de acuerdo con una parte de su comentario. Pueden entenderse sin tener exactamente la misma opinión.','周五，邻居们谈一部电影。Diego 问：“你们觉得怎么样？”Lina 认为故事有趣，但略长。Irene 同意她的一部分看法。即使意见不完全相同，他们也能理解彼此。'],
['Pablo dice: «A mí no me gustó mucho el final». Lina no responde que está equivocado por tener otra preferencia. Pregunta qué parte quiere decir y escucha su explicación. Distinguen entre describir la película y explicar cómo les ha hecho sentir.','Pablo 说：“我不太喜欢结尾。”Lina 没有因为喜好不同就说他错了，而是问指哪部分，并听他的解释。大家区分了描述电影与说明自己感受。'],
['Después piensan en el fin de semana. «¿Qué tal si vamos al parque?», propone Irene. A Diego le viene mal el sábado, pero puede ir el domingo. Ofrece una alternativa con día y hora. Decir simplemente «no» no permite organizar el plan.','随后他们商量周末。Irene 提议去公园。Diego 周六不方便，但周日可以，于是提出具体日期和时间。只说“不行”无法帮助大家安排。'],
['Finalmente acuerdan verse el domingo a las once. Si llueve, buscarán otra actividad. Lina anota el acuerdo y confirma que todos han entendido el mismo lugar. Sabe que una propuesta y una decisión compartida son dos pasos diferentes.','最后大家约定周日十一点见面。如果下雨，就另找活动。Lina 记下约定，确认所有人理解的是同一地点。她知道提议与共同决定是两个不同步骤。']
],['opinión','parecer','historia','acuerdo','final','proponer','alternativa','domingo'],[
['Irene está de acuerdo con una parte de su comentario.','Irene 同意她评论中的一部分。','estar de acuerdo con为固定结构；同意一部分不等于同意全部。'],['A Diego le viene mal el sábado, pero puede ir el domingo.','Diego周六不方便，但周日可以去。','venir bien/mal可说时间是否合适；le标当事者，sábado是被评价的安排。']],
[['询问和表达观点','¿Qué opinas de…?、¿Qué te parece…?与Creo/Pienso que…分别提问和给判断。肯定判断与否定认知的语气继续按主句框架学习，不是只见que就选同一种式。'],['提议与婉拒','¿Qué tal si…?、¿Te apetece…?、Me viene mal…可以组合为提议、说明限制、替代时间。qué tal si 后的本课常见建议用现在直陈式，不强制虚拟。']],
['休闲与社会交往','散步、阅读、体育、家庭聚会、看电影等都可能是休闲方式；不能从一个旧调查百分比推断每个人都如此生活。','邀请别人时问兴趣、时间和预算，把选择权留给对方。拒绝一次活动不必被解释为拒绝友谊。','介绍习惯可用 A menudo…、Suelo…、Los fines de semana…，说明自己或具体人群，不将个人喜好写成全民族事实。'],[
 srChoice('Lina 觉得电影有什么不足？','有点长',['有点长','完全没有故事','没有结尾'],'第一段说un poco larga。'),srChoice('最后约定何时见面？','周日十一点',['周日十一点','周六十一点','周五九点'],'最后一段给出完整安排。'),srInput('同意：Estoy de acuerdo ___ ti.','con','固定搭配estar de acuerdo con。'),srInput('建议：¿Qué tal si ___ al parque?（ir, nosotros，现在时）','vamos','本题指定常见qué tal si＋现在时框架。'),srChoice('朋友拒绝一次活动就一定拒绝友谊吗？','不一定，应理解具体限制',['不一定，应理解具体限制','一定','只看过去时词尾'],'文化部分强调时间和偏好的具体性。'),srChoice('me viene mal 在安排语境常说：','对我来说时间或条件不合适',['对我来说时间或条件不合适','我一定生病了','物品必须坏了'],'按搭配与语境理解，不逐词直译。')]);
sr(13,'准备聚会，也把邀请写清楚','A2',['分配聚会准备任务','写邀请邮件'],[
['Los vecinos quieren organizar una pequeña fiesta. Antes de comprar nada, preguntan qué hay que hacer. Necesitan elegir un día, calcular cuántas personas vienen y decidir quién prepara la comida. No basta con decir que todos deben ayudar: cada tarea necesita una persona y una fecha.','邻居们想办一个小聚会。购物前先问需要做什么：选日期、算人数、决定谁准备食物。只说大家都应帮忙不够，每项任务还要有负责人和时间。'],
['Lina puede escribir las invitaciones. Diego se encarga de las bebidas. Irene dice: «Si vienen diez personas, necesitamos más sillas». La condición no es un hecho confirmado. Primero esperan las respuestas y después ajustan la cantidad de comida.','Lina 可以写邀请，Diego 负责饮品。Irene 说：“如果来十个人，就得多找椅子。”这个条件尚未成为确定事实。他们先等回复，再调整食物数量。'],
['En el correo, Lina escribe un asunto claro: Fiesta del sábado. Saluda a sus amigos, indica el día, la hora y la dirección, y pregunta si pueden venir. También explica qué pueden llevar si quieren colaborar. La invitación no se convierte en una obligación.','Lina 把邮件主题写成“周六聚会”，向朋友问好，注明日期、时间、地址，并问能否参加。她也说明想帮忙的人可以带什么，但邀请不是强制义务。'],
['Antes de enviar el mensaje, revisa los nombres y la información. Para una institución usaría otro tratamiento y explicaría el motivo de forma más formal. Aquí termina con Un abrazo. Comprueba que la relación con los destinatarios y el tono sean coherentes.','发送前，她核对名字和信息。如果写给机构，会换称呼并更正式地说明来意。这封朋友邮件以 Un abrazo 结束。她检查语气是否符合与收件人的关系。']
],['organizar','fiesta','encargarse','invitación','asunto','dirección','destinatario','colaborar'],[
['Si vienen diez personas, necesitamos más sillas.','如果来十个人，我们需要更多椅子。','si从句给条件，vienen配personas；主句necesitamos配我们，两句人称各自判断。'],['La invitación no se convierte en una obligación.','邀请不会变成义务。','convertirse en表示变成，se为动词结构的一部分；强调交际意图区别。']],
[['义务与任务','Hay que…提出一般需要，Tenemos que…明确我们承担，Necesitamos…说明需求，Podemos…说明可做的事。再把任务落实到谁何时完成。'],['邮件结构','主题、称谓、来意、必要信息、希望的回应、结尾与署名按关系组织。朋友邮件与机构邮件不靠一个通用称呼解决所有情境。']],
['姓名、婚姻与称呼','西语地区的姓名制度不同；在当代西班牙，结婚并不意味着女性必须改用丈夫的姓。不要将某些地方、年代的习惯写成整个西语世界的强制规则。','填写表格时分清nombre和apellido(s)，按证件与具体要求填写。不要凭婚姻状态、外貌或姓氏猜对方偏好的称呼。','交往中可问 ¿Cómo prefieres que te llame?；姓名是个人身份信息的一部分，尊重对方实际使用比套用一条旧俗重要。'],[
 srChoice('Diego 负责什么？','饮品',['饮品','所有邀请','买机票'],'第二段说se encarga de las bebidas。'),srChoice('朋友邮件以什么结束？','Un abrazo',['Un abrazo','一张罚单','无人署名'],'最后一段给出结束语。'),srInput('Si ___ diez personas…（venir，现在时）','vienen','条件从句主语diez personas复数。'),srInput('Diego se encarga ___ las bebidas.','de','encargarse de为常见搭配。'),srChoice('当代西班牙结婚后女性必须改丈夫姓吗？','并非如此',['并非如此','全国强制如此','只由邮箱决定'],'文化讲解纠正把某些旧俗普遍化。'),srChoice('邮件主题的主要用途之一是：','帮助收件人快速识别来意',['帮助收件人快速识别来意','替代全部正文','只为展示高级词汇'],'主题应清楚具体，不替代必要信息。')]);
sr(14,'久别重逢，感谢也要说出缘由','A2',['重逢与祝贺','接收礼物并回应'],[
['En la fiesta llega Sara, una amiga a la que Lina no ve desde hace meses. «¡Cuánto tiempo sin verte!», dice Lina. Sara responde que lleva mucho trabajo. Las dos se alegran de encontrarse, pero no suponen que tienen que explicar todos los detalles de su vida.','聚会上来了 Sara，Lina 已有数月没见她。Lina 说“好久不见”。Sara 说最近工作很多。两人为重逢高兴，但没有认为必须交代生活的全部细节。'],
['Sara vive en la ciudad desde hace dos años. También dice: «Hace dos años que trabajo aquí». Las dos estructuras pueden expresar una situación que continúa. No se confunden con «Llegué hace dos años», que sitúa una llegada en el pasado.','Sara 在这座城市住了两年，也说 Hace dos años que trabajo aquí。两种结构可表达仍持续的情况。它们不同于 Llegué hace dos años，后者把一次到达定位于过去。'],
['Después, Irene le entrega a Lina un pequeño regalo. Lina dice: «Gracias por acordarte de mí». Pregunta si puede abrirlo ahora y escucha la respuesta. Al ver el libro, comenta qué le gusta de él, en vez de limitarse a una fórmula sin mirar el objeto.','随后 Irene 给 Lina 一个小礼物。Lina 说：“谢谢你记得我。”她问现在能不能打开，并听对方回应。看见书后，她说出自己具体喜欢什么，而不只是不看礼物地套一句话。'],
['En la conversación, Lina evita preguntas demasiado personales a quienes acaba de conocer. Si alguien no quiere hablar de un tema, cambia de asunto. Una charla amable no exige conocer el salario, la edad o las ideas políticas de todos los invitados.','聊天时，Lina 不对刚认识的人问过于私人的问题。有人不想谈某个话题，她就换话题。友好交流不要求知道所有客人的收入、年龄或政治观点。']
],['reencuentro','desde','hace','regalo','agradecer','acordarse','asunto','invitado'],[
['Hace dos años que trabajo aquí.','我在这里工作两年了。','hace＋时长＋que＋现在时可表达延续到当前；区别llegué hace dos años中的过去定位。'],['Gracias por acordarte de mí.','谢谢你记得我。','gracias por＋原形表达感谢缘由；acordarse de保留de，介词后mí带重音。']],
[['时间延续与过去定位','Vivo aquí desde hace dos años / Hace dos años que vivo aquí可谈持续；Llegué hace dos años谈到达距今多久。先分任务，再选结构。'],['祝贺与感谢','¡Felicidades!可祝贺，Gracias por＋名词/原形给感谢原因。收到礼物时可先道谢、结合场景确认是否当场打开，不把某种习惯强制推广。']],
['私人话题与谈话边界','年龄、收入、健康、宗教和政治等在某些关系中可能敏感，但并非所有人对所有话题的边界相同。','先从共同场景、兴趣或活动聊起，留意回应；对方不愿谈时尊重并转换，不把某个年龄门槛当成绝对规则。','可以用 Si no te importa que pregunte… 等方式缓和，但礼貌词不意味着对方必须回答。愿意倾听和接受不回答，也是交际能力。'],[
 srChoice('Sara 在这座城市住了多久？','两年',['两年','两天','二十年'],'第二段说明desde hace dos años。'),srChoice('Irene 送了什么？','一本书',['一本书','一张车票','一双鞋'],'第三段见到的礼物是el libro。'),srInput('Gracias ___ acordarte de mí.','por','gracias por引感谢原因。'),srInput('Hace dos años que ___ aquí.（trabajar, yo）','trabajo','本题表达持续到现在的工作，使用现在时trabajo。'),srChoice('别人不愿回答私人问题时，应：','尊重并转换话题',['尊重并转换话题','因为用了礼貌词就强迫回答','认定整个国家都冷漠'],'文化解读强调个人边界。'),srChoice('Llegué hace dos años 主要说明：','到达发生在两年前',['到达发生在两年前','现在正到达两年','所有动作永不结束'],'与延续结构分开。')]);
sr(15,'节日问候之后，读懂一份做菜说明','A2',['写贺卡与祝福','跨文化分享食物和节庆'],[
['En diciembre, Lina escribe una tarjeta para sus vecinos. Empieza con una felicitación, añade un deseo concreto y termina con su nombre. Escribe «Felices fiestas». Si se refiere solo al Año Nuevo, puede decir «Feliz Año Nuevo». La forma depende de lo que nombra.','十二月，Lina 给邻居写贺卡：先祝贺，再加具体祝愿，最后署名。她写 Felices fiestas；若只指新年，可说 Feliz Año Nuevo。形式取决于所指的名词。'],
['Los amigos también hablan de la comida que van a compartir. Lina explica una receta sencilla de ensalada. Se lavan los tomates, se cortan y se mezclan con otros ingredientes. Los verbos van en plural porque los tomates son el sujeto de estas formas con se.','朋友们也谈起将分享的食物。Lina 介绍一份简单沙拉食谱：洗番茄、切番茄、与其他食材混合。这些 se 结构中番茄是主语，因此动词用复数。'],
['Irene cuenta que en su familia comen uvas durante las campanadas de Nochevieja. No piensa que todo el mundo tenga que hacerlo. Otra amiga celebra de otra manera. Comparan las costumbres y preguntan qué significa cada gesto para quien lo practica.','Irene 说她家在除夕钟声中吃葡萄，但不认为每个人都必须照做。另一位朋友有不同庆祝方式。大家比较习俗，询问每种做法对参与者有什么意义。'],
['Lina aprende nombres de fiestas, pero también consulta el calendario del lugar donde vive. Una celebración puede ser nacional, autonómica, local o familiar. Las fechas de algunas fiestas cambian de un año a otro. Una lista de un libro no sustituye un calendario actual.','Lina 学习节日名称，也查居住地日历。庆祝可能属于全国、自治区、地方或家庭，有些节日日期年年变化。书上的列表不能替代当年日历。']
],['tarjeta','felicitación','fiesta','receta','tomate','mezclar','campanada','Nochevieja'],[
['Se lavan los tomates, se cortan y se mezclan.','洗番茄、切开并混合。','被动se的主语为复数tomates，后续省略主语的动词继续配它。'],['La forma depende de lo que nombra.','形式取决于所指名称。','depender de保留de；lo que概括所命名的内容，不指某个男性对象。']],
[['贺词','Feliz＋单数节日名与Felices＋复数名词配合；desear a alguien＋名词可表达祝愿，如Te deseo un buen año。'],['食谱的se','Se lava el tomate / Se lavan los tomates要按被动主语数配合；食谱还会用原形或命令等其他写法，读时先认结构。']],
['节日与不同日历','Año Nuevo、Reyes、Semana Santa、Fallas等名称可用于了解不同庆祝，但不能把所有节日都当成全国统一放假日。','Semana Santa等日期随年份变化；地方节日、家庭传统与宗教实践也不完全相同。课堂中学会名称，实际安排再查当地当年日历。','分享自己习惯时说 En mi familia… 或 En mi ciudad… 能给出范围。不同做法可互相解释，无需排名哪一种才算真正过节。'],[
 srChoice('Lina 在贺卡上写的复数问候是：','Felices fiestas',['Felices fiestas','Feliz fiestas','Felices año'],'第一段给出该表达。'),srChoice('食谱中被清洗的食物是：','番茄',['番茄','面包','鸡蛋'],'第二段的tomates。'),srInput('Se ___ los tomates.（lavar）','lavan','被动主语tomates复数。'),srInput('___ Año Nuevo.（feliz，配单数）','feliz','Año单数，feliz不变复数。'),srChoice('节日列表是否等于当年当地放假日历？','不是，需要核对范围和年份',['不是，需要核对范围和年份','永远相同','只看动词词尾'],'文化讲解强调时点和地区。'),srChoice('En mi familia… 这样开头的好处之一：','明确习惯适用范围',['明确习惯适用范围','保证所有国家都一样','省去所有事实核对'],'不把家庭习惯推广为全体事实。')]);
sr(16,'照片里的那一天','A2',['看相册辨认人物','回忆经历与感叹时间'],[
['Una tarde, Pablo enseña un álbum en el móvil. Lina ve a un chico con una guitarra y pregunta quién es. «Es mi primo», responde Pablo. Para identificar a una persona en una foto, primero necesita saber qué imagen están mirando los dos.','一天下午，Pablo 展示手机相册。Lina 看见一个拿吉他的男孩，问是谁。Pablo 说是自己的表亲。辨认照片人物时，先要确保双方看的是同一张照片。'],
['La foto es de una fiesta del año pasado. Pablo fue con sus primos y tocó varias canciones. Lina pregunta cuándo terminó la fiesta y cómo volvieron a casa. Las respuestas sitúan los hechos y permiten ordenar la historia.','照片拍于去年一场聚会。Pablo 与表亲一起去，弹了几首曲子。Lina 问聚会何时结束、怎样回家。回答能定位事件并把故事排序。'],
['En otra foto hay muchos amigos junto a un campo de fútbol. «¡Cuánta gente!», dice Lina. Después comenta: «¡Qué rápido pasa el tiempo!». La primera expresión destaca cantidad; la segunda se centra en cómo ocurre algo.','另一张照片里，足球场旁有很多朋友。Lina 感叹人多，又说时间过得真快。前一个表达突出数量，后一个突出发生的方式或程度。'],
['Pablo dice que se lo pasó muy bien aquel día. Lina entiende que pasárselo bien es una expresión completa. No traduce cada pronombre por separado. Para terminar, compara su propia experiencia y escucha sin convertir una anécdota en una regla sobre todo un país.','Pablo 说那天玩得很开心。Lina 理解 pasárselo bien 是整体表达，不把每个代词逐一硬译。最后她分享自己的经历，并认真听，不把一则轶事变成关于整个国家的规则。']
],['álbum','primo','guitarra','foto','canción','campo','gente','pasárselo'],[
['Las respuestas sitúan los hechos y permiten ordenar la historia.','回答能定位事实并帮助排序故事。','两个谓语同配复数respuestas；permitir后ordenar为原形。'],['Se lo pasó muy bien aquel día.','他那天玩得很开心。','pasárselo bien按整体记，pasó在本句配第三人称过去；lo不必恢复成具体阳性物品。']],
[['询问照片','¿Quién es?、¿De cuándo es la foto?、¿Dónde la hiciste/tomaste?各问人物、时间或地点；hacer/tomar/sacar fotos有地区和搭配习惯。'],['感叹与体验','cuánto在名词前配性数，qué可修饰形容词或副词。pasárselo bien常作整体活动体验，不能把这里的lo统一认作某件物品。']],
['体育与个人兴趣','fútbol、natación、ciclismo、baloncesto、senderismo等提供描述兴趣和活动的词汇，不等于每个人都支持同一项目或球队。','谈体育可问 ¿Practicas algún deporte? 或 ¿Qué te gusta ver?。参与一项运动和观看比赛也是不同兴趣。','教材调查图表可练比较与范围表达，但数字应带上时间、样本和口径；不要把某份旧排名当成所有年份的实时事实。'],[
 srChoice('拿吉他的男孩是 Pablo 的谁？','表亲',['表亲','老师','司机'],'第一段回答mi primo。'),srChoice('聚会是什么时间的？','去年',['去年','明年','每天'],'第二段说明del año pasado。'),srInput('去年他去了：___ con sus primos.（ir, él）','fue','ir的第三人称单数简单过去时为fue。'),srInput('感叹人多：¡___ gente!','cuánta','gente语法阴性单数，用cuánta。'),srChoice('体育调查排名应如何理解？','结合年份、样本和统计口径',['结合年份、样本和统计口径','当作永久不变','直接推断每个人的兴趣'],'文化说明强调统计范围。'),srChoice('pasárselo bien 在本文表示：','某次活动中过得开心',['某次活动中过得开心','把一个物品传得好','所有人必须独处'],'按表达整体理解。')]);
sr(17,'谈婚礼时，先听个人经历','A2',['读婚礼消息与日期','比较不同庆祝形式'],[
['En el portal, los vecinos leen una invitación de boda. El mensaje indica el día, la hora y el lugar de la ceremonia. Lina comprueba que la fecha del calendario coincide con la invitación. No quiere confundir el día de la ceremonia con el de una cena anterior.','楼门口，邻居们读到婚礼邀请，上面写着日期、时间和仪式地点。Lina 核对日历，避免把仪式日期与前一天晚餐混同。'],
['Clara cuenta que se casó hace diez años. Su boda fue civil y después hubo una comida con amigos. Otro vecino habla de una ceremonia religiosa. Son experiencias diferentes. Nadie usa una historia personal para decidir cómo deben casarse los demás.','Clara 说自己十年前结婚，办的是民事仪式，之后与朋友吃饭。另一位邻居谈宗教仪式。这是不同个人经历，没人以自己的故事规定别人必须怎样结婚。'],
['En la conversación aparecen las formas hizo, tuvo y vinieron. Lina las compara con los infinitivos hacer, tener y venir. Algunas formas de pasado cambian de raíz. También distingue dijo de dijeron y no inventa una i en dijieron.','谈话中出现 hizo、tuvo、vinieron，Lina 将它们与 hacer、tener、venir 对照。有些过去时会改变词干，她也区分 dijo、dijeron，不凭空在 dijieron 中添 i。'],
['Al hablar de una celebración, alguien exclama «¡Vivan los novios!». Lina observa el plural. El mismo deseo puede tener otra forma con un sustantivo singular. Para felicitar a personas concretas, lo importante es respetar cómo ellas describen su relación y su ceremonia.','谈起庆祝，有人喊“祝新人幸福万岁”。Lina 注意到复数。类似祝愿遇到单数名词时形式也会不同。祝贺具体的人时，应尊重他们怎样描述自己的关系与仪式。']
],['boda','ceremonia','invitación','civil','religioso','casarse','novio','celebración'],[
['Su boda fue civil y después hubo una comida con amigos.','她的婚礼是民事仪式，之后与朋友吃饭。','fue在此为ser过去时；hubo为存在义haber，不按comida的其他信息改人称。'],['Nadie usa una historia personal para decidir cómo deben casarse los demás.','没人用个人经历决定别人应怎样结婚。','nadie为否定主语；cómo引间接疑问，deben配los demás，casarse保持原形。']],
[['婚礼与关系动词','casarse con alguien与estar casado/a con alguien分事件与状态；civil通常不因阴性写成civila。'],['祝愿形式','¡Vivan los novios! 与 ¡Viva la amistad!中动词配所祝愿的主语数；这不是照搬tú肯定命令的规则。']],
['婚庆方式与实际邀请','民事与宗教仪式都可能出现，具体流程、参加方式和宴会习惯因个人、地区和机构不同。','参加前读清邀请中的地点、时间、着装及回应要求；不确定可礼貌询问，不能把一份教材的座位安排当成所有婚礼的规范。','祝贺可用 ¡Felicidades!；说明过往经历时应标明是自己的或某次仪式，不把传统描述变成他人的义务。'],[
 srChoice('Clara 的婚礼是什么形式？','民事仪式',['民事仪式','学校考试','体育比赛'],'第二段说su boda fue civil。'),srChoice('她何时结婚？','十年前',['十年前','昨天','明年'],'第二段说hace diez años。'),srInput('decir，简单过去时，ellos：','dijeron','j词干组的第三人称复数用-eron。'),srInput('复数祝愿：¡___ los novios!（vivir）','vivan','本句祝愿框架配复数主语los novios。'),srChoice('参加婚礼前最应依据什么确认安排？','具体邀请和当事人的说明',['具体邀请和当事人的说明','所有国家必须同一座位图','只看姓氏猜仪式'],'文化说明强调实际邀请与个人选择。'),srChoice('civil 描述 la ceremonia 时：','仍可用 civil',['仍可用 civil','必须 civila','变成 civilo'],'该形容词不按这种方式造阴性-a形式。')]);
sr(18,'从人物生平，读到过去的生活背景','A2',['阅读人物传记','描述过去的家乡'],[
['En clase, Lina lee una breve biografía de Pablo Picasso. Nació en Málaga en 1881 y murió en Francia en 1973. Entre sus obras se encuentran Las señoritas de Aviñón y Guernica. Lina separa las fechas, los lugares y los nombres de las obras antes de intentar recordarlo todo.','课上 Lina 读毕加索小传。他于1881年生于马拉加，1973年在法国逝世，作品包括《亚维农少女》和《格尔尼卡》。Lina 先区分日期、地点和作品名，而不是一次硬背所有信息。'],
['La biografía utiliza formas de pasado para ordenar acontecimientos. Pero una vida no se explica solo con una lista de años. También hacen falta contextos: dónde vivía una persona, qué aprendía y cómo era la época. Lina aprende a distinguir los hechos de las interpretaciones.','传记用过去时排列事件，但人生不能只靠年份列表解释，还需要背景：住在哪里、学什么、时代如何。Lina 学着区分事实与解释。'],
['Clara recuerda el pueblo donde vivía de niña. Había un río y en invierno hacía frío. Los sábados iba a ver a sus abuelos. Un día encontró una fotografía antigua. La descripción del entorno y el acontecimiento puntual tienen funciones diferentes en la narración.','Clara 回忆童年住的村庄：有河，冬天冷，周六常去看祖辈。有一天她发现一张旧照片。环境描述与一次具体事件在叙事中承担不同功能。'],
['Después leen una noticia cultural. Lina mira el nombre del medio, la fecha y quién firma el texto. Una noticia, una opinión y una publicidad no son lo mismo. Para comprender mejor, pregunta qué afirma el artículo y qué pruebas ofrece, no solo cuántas palabras nuevas contiene.','随后他们读一则文化新闻。Lina 看媒体名称、日期和作者。新闻、观点与广告不是一回事。为了读懂，她不仅数生词，还问文章主张什么、提供了什么依据。']
],['biografía','nacer','morir','obra','pueblo','río','invierno','medio'],[
['Una vida no se explica solo con una lista de años.','人生不能只靠年份列表解释。','se结构把人生如何被解释作为重点，solo限制方式；不是否认年份有用。'],['El pueblo donde vivía de niña tenía un río.','她小时候住的村庄有条河。','donde引地点关系从句，vivía铺生活背景；主句tenía也描述当时状态。']],
[['叙事的两个镜头','简单过去推进边界事件，未完成时展开背景与习惯；重复式活动也可按总览视角用简单过去，不能只靠长短决定。'],['进行结构','estar＋副动词突出过程；leyendo与leído不同。新闻在读什么与新闻已经读过，结构和参照都要重新判断。']],
['媒体与信息解读','El País、El Mundo、ABC等可作为认识西班牙报刊名称的例子，但不把旧教材中的销量或受欢迎排名当成当前事实。','区分新闻报道、评论、专栏与广告；查日期、作者、来源和引用证据，留意标题是否超出正文能支持的范围。','阅读能力包括语言解码，也包括判断文本在做什么。对于人物传记，应区分出生逝世等事实、作者的评价和仍可讨论的解释。'],[
 srChoice('文章给出的 Picasso 出生地是：','Málaga',['Málaga','Madrid','巴黎'],'第一段给出Nació en Málaga。'),srChoice('Clara 过去冬天的家乡天气如何？','冷',['冷','每年都特别热','完全没有说明'],'第三段说hacía frío。'),srInput('过去习惯：Los sábados ___ a ver a sus abuelos.（ir, ella）','iba','按过去习惯视角用ir未完成时iba。'),srInput('正在阅读：Está ___.（leer，副动词）','leyendo','leer的副动词leyendo，区别分词leído。'),srChoice('读新闻时应同时注意：','日期、作者、文本类型和证据',['日期、作者、文本类型和证据','只数生词','标题一定等于全部事实'],'媒体解读强调多维核对。'),srChoice('vivía 在童年环境叙述中主要用于：','展开过去生活背景',['展开过去生活背景','证明后来一定没住过','自动表示将来'],'未完成视角不等于现实行为没结尾。')]);
sr(19,'Cuando el plan cambia, la información importa','B1',['Una reserva que no aparece','Explicar el problema y negociar'],[
['Al llegar al alojamiento, Nora descubre que su reserva no aparece en el sistema. Tiene un correo de confirmación, pero la recepcionista solo encuentra una solicitud antigua con otra fecha. Nora está cansada y podría enfadarse. Sin embargo, decide separar lo que sabe de lo que todavía necesita comprobar.','Nora 到住宿地点后，发现系统没有预订记录。她有确认邮件，但前台只找到另一日期的旧申请。她很累，也可能生气，不过决定先区分已知信息与仍须核实的部分。'],
['Primero muestra el número de reserva y pregunta qué datos faltan. No afirma que la empleada haya cometido el error: todavía no conoce la causa. La recepcionista revisa los mensajes y llama a una compañera. Mientras esperan, Nora resume el problema en dos frases para evitar que cada persona tenga que empezar de nuevo.','她先出示预订号，询问缺哪些资料，没有断言前台犯了错，因为原因尚不明确。前台查消息并给同事打电话。等待时，Nora 用两句话概括问题，避免每个人都得从头了解。'],
['Finalmente encuentran una modificación que no se había guardado correctamente. No queda una habitación del mismo tipo, pero ofrecen otra y explican la diferencia de precio. Nora pregunta si puede verla antes de aceptar. También solicita que cualquier cambio quede confirmado por escrito, con las fechas y el importe final.','最后发现一次修改没有正确保存。原房型已无空房，工作人员提供另一间并说明差价。Nora 问能否先看房再接受，也要求任何变更都用书面确认，列出日期和最终金额。'],
['El acuerdo no es exactamente el plan original, pero las dos partes entienden qué se ha decidido. Al día siguiente, Nora cuenta la experiencia sin convertirla en una acusación contra todos los hoteles de una ciudad. Distingue el hecho, la explicación recibida y su opinión sobre la solución. Esa diferencia hace su relato más claro y más justo.','协议与原计划不完全相同，但双方清楚决定了什么。次日 Nora 讲述经历时，没有把它变成对整座城市所有酒店的指责。她区分事实、收到的解释及自己对解决方案的评价，因此讲述更清楚，也更公允。']
],['alojamiento','reserva','confirmación','solicitud','modificación','importe','acuerdo','acusación'],[
['Todavía no conoce la causa.','她还不知道原因。','todavía no表当前尚未掌握；不知道原因与断言对方有错是不同立场。'],['Una modificación que no se había guardado correctamente.','一次未被正确保存的修改。','关系从句限定modificación；había guardado相对到达参照更早，se将处理结果置于焦点。']],
[['事实、推断、请求','报告已有证据，再说明缺口，最后提出具体请求；三者用不同表达，不把猜测直接升级为指责。'],['书面确认','quedar confirmado por escrito、fechas、importe final帮助把协商转为双方可核对的信息。']],
['解决服务问题','礼貌不等于放弃清楚说明需求，强硬也不等于越多指责越有效。','先提供可核对信息，再问缺口与替代方案；确认结果时写清金额、时间和条件。','把单次经验讲成一个具体事件，避免无证据推广为整个地区或行业的固定特征。'],[
 srChoice('系统先找到什么？','日期不同的旧申请',['日期不同的旧申请','完整正确的新订单','Nora的机票'],'首段说明otra fecha的旧solicitud。'),srChoice('Nora 接受替代房间前想做什么？','先看看房间',['先看看房间','删除邮件','拒绝一切沟通'],'第三段说verla antes de aceptar。'),srInput('书面确认：por ___.','escrito','por escrito是常见固定表达。'),srInput('更早未保存：no se ___ guardado.','había','过去参照之前的完成结构用había＋分词。'),srChoice('Nora 为什么不立刻断言前台犯错？','她还不知道原因',['她还不知道原因','她从不需要房间','所有错误都不重要'],'文章区分已知事实和归责推断。'),srChoice('叙事更清楚的一种做法是：','区分事实、解释和评价',['区分事实、解释和评价','把所有推断写成事实','隐去全部时间信息'],'最后一段给出明确的阅读解读线索。')]);
sr(20,'Un mensaje para organizarse mejor','B1',['Una fecha ambigua','Reescribir para el lector'],[
['El grupo de estudio prepara una presentación. El lunes, alguien escribe: «Lo mandamos mañana». El martes, otra persona lee el mensaje y entiende que el envío será el miércoles. No hay un gran problema de gramática en la frase, pero sí falta una referencia clara para quien la lee en otro momento.','学习小组准备报告。周一有人写“我们明天发”，周二另一人读到，以为周三才发。句子的语法未必有大问题，但对后来阅读的人缺少清晰时间参照。'],
['Marta propone cambiar el mensaje por una fecha y una hora concretas. También pregunta quién reúne las distintas partes del documento. Hasta ese momento, cada miembro había pensado que lo haría otra persona. La expresión «nos encargamos nosotros» no había aclarado qué tarea correspondía a cada uno.','Marta 建议写明日期、时刻，并问谁负责汇总文档。此前每个人都以为会由别人做。“我们负责”没有说明每人对应哪项任务。'],
['Reescriben el acuerdo: antes del jueves a las seis, cada persona debe subir su parte; después, Marta revisará las referencias y Leo enviará el archivo final. Añaden dónde se guarda la versión definitiva. Así pueden comprobar el cumplimiento sin depender de una interpretación diferente de palabras como luego o pronto.','他们重写约定：周四六点前，各人上传自己的部分；随后 Marta 核对参考资料，Leo 发送最终文件，并说明最终版保存在哪。这样核对执行情况不再依赖对“随后”“很快”等词的不同理解。'],
['El ejercicio les enseña que revisar no consiste solo en buscar faltas de ortografía. Un texto puede tener palabras correctas y resultar difícil de usar. Al revisarlo, conviene preguntarse qué sabe el destinatario, qué necesita hacer y qué información no puede adivinar. Escribir con precisión también es una forma de cuidar el trabajo de los demás.','这个练习让他们明白，修改不只是找拼写错误。一个文本即使词都写对，也可能不好用。修改时应问读者已知什么、需要做什么、有哪些信息无法猜到。写清楚也是尊重他人工作的方式。']
],['referencia','reunir','documento','corresponder','definitivo','cumplimiento','destinatario','precisión'],[
['Cada miembro había pensado que lo haría otra persona.','每位成员此前都以为另一人会做。','había pensado标更早想法；haría为过去视角下的未来行动，不能只按中文会就统一现在时。'],['Un texto puede tener palabras correctas y resultar difícil de usar.','文本可以用词正确，却难以使用。','poder后两个并列原形tener/resultar；语法正确与交际可用性分开。']],
[['指示语参照','mañana、luego等依赖说话时点和情境。异步消息中可以用具体日期与职责减少误解。'],['作者与读者','写作应检查信息完整性、操作顺序与指代，而不只检查单个词的拼写。']],
['协作沟通','明确责任不是不信任，而是减少成员间不同理解造成的重复工作。','可把人员、动作、期限、存放位置四项列出，再写成自然连贯的信息。','复述约定并请对方确认，通常比未经核实就认为所有人都懂更有效。'],[
 srChoice('周二读到mañana的人以为哪天发送？','周三',['周三','周一','当天已发送'],'首段描述参照误解。'),srChoice('谁最终发送文件？','Leo',['Leo','Marta','未指定'],'第三段明确Leo enviará。'),srInput('过去想法中的将来：pensó que otra persona lo ___.（hacer，条件式）','haría','过去叙述视角的将来可用条件式haría。'),srInput('Antes ___ jueves…（de＋el）','del','普通冠词结构de＋el缩合del。'),srChoice('这篇文章的核心观点之一：','修改也要检查读者能否据此行动',['修改也要检查读者能否据此行动','只查拼写就足够','越含糊越礼貌'],'最后一段解释交际可用性。'),srChoice('写清责任与期限的直接作用是：','减少不同理解造成的协作误差',['减少不同理解造成的协作误差','保证所有人永不犯错','取代所有沟通'],'文章未保证绝对无误，只说明减少误解。')]);
sr(21,'Lo que una encuesta permite afirmar','B2',['Leer un resultado','Revisar una conclusión'],[
['Una academia publica que el setenta por ciento de sus estudiantes prefiere estudiar por la mañana. A partir de ese dato, un anuncio sostiene que las clases matinales garantizan mejores resultados para cualquier persona. La frase parece convincente: incluye un porcentaje, menciona estudiantes y ofrece una conclusión sencilla. Sin embargo, el salto entre el dato y la promesa requiere una revisión.','一家学校公布，七成学生更喜欢上午学习。广告据此声称，上午课保证任何人都取得更好成绩。这句话看似有说服力：有百分比、有学生、有简单结论。但从数据到承诺的跨越需要检查。'],
['La encuesta pregunta por preferencias, no mide cuánto se aprende. Tampoco sabemos cómo se eligió a los participantes, cuántas personas respondieron ni si pertenecen a una población comparable con todos los posibles alumnos. Quienes ya asisten a una academia pueden tener horarios, recursos y motivaciones distintos de los de otras personas. Ninguna de estas observaciones vuelve inútil la encuesta; simplemente delimita lo que permite afirmar.','调查问的是偏好，没有测量学到了多少。我们也不知道如何选参与者、有多少人回答、样本是否能代表所有潜在学生。已在该校上课的人，在时间、资源、动机上可能不同。指出这些不等于调查无用，而是限定它能支持什么。'],
['Para comprobar si un horario mejora el aprendizaje harían falta otras medidas y un diseño que permitiera comparar explicaciones alternativas. Tal vez influyan el descanso, la experiencia previa o la posibilidad de asistir con regularidad. Confundir una preferencia con una causa oculta esas diferencias y transforma una observación limitada en una recomendación universal.','若要判断某时段是否提高学习效果，需要其他测量与能比较替代解释的研究设计。睡眠、既有经验或能否规律出勤，都可能影响结果。把偏好混作原因，会遮蔽这些差别，并把有限观察变成普遍建议。'],
['Una conclusión más prudente diría que, entre las personas que respondieron a esa encuesta, la mayoría manifestó una preferencia por la mañana. A continuación señalaría qué información falta. Ser prudente no exige evitar toda conclusión: exige ajustar la fuerza de las palabras a la fuerza de la evidencia. Ese hábito sirve tanto para leer publicidad como para revisar nuestros propios argumentos.','更审慎的结论会说，在这次调查的回答者中，多数人表示偏好上午，再说明还缺哪些信息。审慎不是拒绝一切结论，而是让措辞强度与证据强度相称。这个习惯既适合读广告，也适合修改自己的论证。']
],['encuesta','garantizar','porcentaje','población','motivación','delimitar','evidencia','prudente'],[
['Ninguna de estas observaciones vuelve inútil la encuesta; simplemente delimita lo que permite afirmar.','这些观察并不让调查无用，而是限定它能支持的主张。','ninguna作否定主语；lo que概括允许主张的内容，避免把批评范围夸大为全盘否定。'],['Un diseño que permitiera comparar explicaciones alternativas.','一种能比较其他解释的设计。','未确定目标设计的关系从句用虚拟式permitiera；不是报告已有设计的实际功能。']],
[['证据与措辞','preferir不是aprender más，mayoría不是todos，observar不等于garantizar。阅读时逐项检查主张扩大了什么。'],['限制不等于无用','批判阅读同时问数据支持什么、尚不支持什么；拒绝虚假确定，也不把所有研究一概否定。']],
['公开信息与论证责任','带数字的文本仍需要来源、样本和测量范围。','写自己的建议时可明确适用人群与条件，并区分经验、统计结果与因果论断。','把证据限制说清楚，可以增强沟通的可信度，而非只是给文字添加一两个表示不确定的副词。'],[
 srChoice('调查实际测量了什么？','学习时段的偏好',['学习时段的偏好','所有人的真实学习效果','睡眠的生理指标'],'第二段明确pregunta por preferencias。'),srChoice('文章认为调查毫无价值吗？','不是，而是要限定可支持的结论',['不是，而是要限定可支持的结论','是，全部调查都无用','认为百分比保证因果'],'第二段指出不使调查无用。'),srInput('未确定目标设计：un diseño que ___ comparar…（permitir，-ra）','permitiera','描述所需但未确定的设计，使用虚拟式未完成形式。'),srInput('la mayoría no equivale a ___.（所有人，填todos）','todos','多数与全部是不同范围。'),srChoice('更稳妥的结论应保留什么？','回答者范围与偏好这一测量内容',['回答者范围与偏好这一测量内容','改写成全国因果保证','删掉一切结果'],'最后一段示范限定范围。'),srChoice('本文主要批评的是：','从有限偏好数据跳到普遍效果保证',['从有限偏好数据跳到普遍效果保证','所有早晨上课行为','任何人表达个人喜好'],'阅读应识别主张跳跃，不替作者扩大批评对象。')]);
sr(22,'Una decisión compartida no necesita una voz única','B2',['Comprender el desacuerdo','Diseñar una decisión revisable'],[
['Un equipo debe elegir cómo presentar los resultados de un proyecto. Dos miembros prefieren una exposición breve; otros quieren incluir cada detalle. En la primera reunión, ambas partes describen su opción como la única profesional. Cuanto más repiten esa etiqueta, menos explican qué problema intentan resolver y más difícil resulta comparar las propuestas.','团队要决定项目成果怎样展示。两人偏好简短汇报，其他人想放入所有细节。第一次会议，双方都称自己的方案唯一专业。越重复这标签，越少说明要解决什么问题，也越难比较方案。'],
['La coordinadora propone cambiar la pregunta. En lugar de decidir quién tiene mejor gusto, pide identificar al público, el tiempo disponible y las acciones que se espera que tome después. Descubren que la audiencia necesita comprender tres conclusiones y disponer de un documento para consultar los datos. La discrepancia no desaparece, pero ahora puede relacionarse con necesidades concretas.','协调者建议换个问题：不判断谁品味更好，而是明确受众、可用时间，以及希望听众之后做什么。他们发现，受众需要理解三项结论，并有文件可查数据。分歧没有消失，但现在能与具体需求联系。'],
['Acuerdan preparar una presentación corta acompañada de un anexo. Antes de considerarla definitiva, otra persona comprobará si puede recuperar del material la información necesaria. Si el ensayo revela dificultades, modificarán la estructura. El acuerdo incorpora así una forma de revisión, en vez de tratar la primera decisión como una victoria que nadie puede cuestionar.','大家决定做简短展示并附补充材料。在定稿前，请另一人检查能否从中找到所需信息。试用若发现困难，就调整结构。协议于是包含了修改机制，而不把最初决定当作不可质疑的胜利。'],
['La experiencia no demuestra que toda discusión tenga una solución intermedia ni que los conflictos de valores se resuelvan con una lista. Muestra algo más limitado: cuando un desacuerdo gira en torno a medios y objetivos verificables, hacer explícitos los criterios puede mejorar la decisión. Reconocer ese límite evita convertir una herramienta útil en otra receta universal.','这个经历不证明每次争论都有折中方案，也不证明价值冲突靠清单就能解决。它说明的是较有限的一点：当分歧围绕手段与可核实目标时，明确标准可能改善决策。认清边界，才能避免把有用工具变成又一万能配方。']
],['desacuerdo','exposición','coordinadora','audiencia','anexo','definitivo','criterio','verificable'],[
['Las acciones que se espera que tome después.','希望受众之后采取的行动。','两层从句分别处理被修饰的acciones和所期望行为，tome的隐含主语为受众，不按acciones复数改tomen。'],['En vez de tratar la primera decisión como una victoria que nadie puede cuestionar.','而非把最初决定当成没人能质疑的胜利。','en vez de引对比替代，que修饰victoria；否定和情态表达共同限定可质疑性。']],
[['比较的标准','先明确目标、受众和约束，再比较方案；专业之类标签不自动提供判断依据。'],['论证的边界','作者主动限制适用范围，不应把局部经验改写成所有冲突都能解决的承诺。']],
['协商与可修订性','共享决定可以保留不同意见，同时明确当前选择和复核条件。','要求具体标准不等于要求所有人价值观一致；有些分歧需要进一步谈判或接受差异。','读论证时特别留意作者何处扩大、何处限定结论，并用实际证据判断是否越界。'],[
 srChoice('受众实际需要什么？','三项结论与可查数据的文件',['三项结论与可查数据的文件','所有细节都口头重复','只看专业标签'],'第二段明确双重需求。'),srChoice('定稿前会怎样检查？','请另一人试用材料找所需信息',['请另一人试用材料找所需信息','不允许任何质疑','只投票选字数最多的'],'第三段说明复核方式。'),srInput('未发生的试用条件：Si el ensayo ___ dificultades…（revelar，现在时）','revela','本题开放条件用现在直陈式。'),srInput('en vez ___ tratar… 只填介词。','de','固定结构en vez de＋原形。'),srChoice('文章是否证明所有争论都有中间解？','没有，作者明确限制结论',['没有，作者明确限制结论','证明了且适用全部价值冲突','没有提出任何判断'],'最后一段明确否定这种过度推广。'),srChoice('更接近本文核心建议的是：','用可检验的目标与标准比较方案并保留复核',['用可检验的目标与标准比较方案并保留复核','以专业标签取代证据','禁止所有不同意见'],'文章强调具体标准与可修订性。')]);
